def max_product(num_str: str, N: int, K: int) -> int:
    """
    Function: max_product
    Parameters:
    num_str (str): The number string.
    N (int): The length of the number string.
    K (int): The number of multiplication signs to insert.
    Returns: The maximum product that can be obtained by inserting K multiplication signs into the number string.
    """
    if K == 0:
        return 1
    elif K == 1:
        return int(num_str)
    else:
        max_product = 0
        for i in range(N-K+1):
            product = int(num_str[i])
            for j in range(i+1, i+K):
                product *= int(num_str[j])
            max_product = max(max_product, product)
        return max_product

