def verify_isbn(isbn: str) -> str:
    if len(isbn) != 13:
        raise ValueError("Invalid ISBN length")
    if isbn[3] != "-" or isbn[8] != "-" or isbn[12] != "-":
        raise ValueError("Invalid ISBN format")
    checksum = sum(int(digit) * (i + 1) for i, digit in enumerate(isbn[:-1])) % 11
    if checksum == 10:
        checksum = "X"
    if isbn[-1].upper() != checksum:
        return isbn[:-1] + checksum
    return "Right"

