def next_permutation(perm):
    # Find the first element from the end that is smaller than the following element
    for i in range(len(perm) - 1, -1, -1):
        if perm[i] < perm[i + 1]:
            break

    # If such element is not found, it means we are in the last permutation
    if i == 0:
        return False

    # Find the first element larger than the current element before the one we found
    for j in range(len(perm) - 1, i, -1):
        if perm[j] > perm[i]:
            break

    # Swap the two elements
    perm[i], perm[j] = perm[j], perm[i]

    # Reverse the elements after the first smaller number
    perm[i + 1:] = perm[i + 1:][::-1]

    return True

